from __future__ import annotations

from pydantic import Field
from typing_extensions import NotRequired, TypedDict

from ..core import UNSET, Optional, SdkBaseModel


class Tenant(SdkBaseModel):
    """A Tenant resource represents a tenant in the service. A tenant is a group or entity that shares common access
    with specific privileges for resources like jobs. Customer may create multiple tenants to provide data isolation for
    different groups."""

    name: Optional[str] = UNSET
    """Required during tenant update. The resource name for a tenant. This is generated by the service when a tenant is
    created. The format is "projects/{project_id}/tenants/{tenant_id}", for example, "projects/foo/tenants/bar"."""

    external_id: Optional[str] = Field(default=UNSET, alias="externalId")
    """Required. Client side tenant identifier, used to uniquely identify the tenant. The maximum number of allowed
    characters is 255."""


class TenantDict(TypedDict):
    name: NotRequired[str]
    external_id: NotRequired[str]
